/* eslint-disable max-len */
import { Component, OnInit, ViewChild } from '@angular/core';
import { SafeUrl, Title, Meta, DomSanitizer } from '@angular/platform-browser';
import { ActivatedRoute, Router } from '@angular/router';
import { IonContent, LoadingController, ToastController } from '@ionic/angular';
import { G } from 'src/app/core/common/G';
import { GAccount } from 'src/app/core/common/GAccount';
import { GResponse } from 'src/app/core/common/GResponse';
import { SharedIonic } from 'src/app/core/common/SharedIonic';
import { Urls } from 'src/app/core/common/Urls';
import { IArticleDetailModel } from 'src/app/data/model/article/ArticleDetailModel';
import { IArticleTagModel } from 'src/app/data/model/article/ArticleModel';
import { TeacherModel } from 'src/app/data/model/person/TeacherModel';
import { IHelpfulLinkModel } from 'src/app/data/model/site/SliderModel';
import { ArticleService } from 'src/app/data/service/article/article.service';

@Component({
  selector: 'app-product-article-by-id',
  templateUrl: './product-article-by-id.component.html',
  styleUrls: ['./product-article-by-id.component.scss']
})
export class ProductArticleByIdComponent implements OnInit {

  @ViewChild(IonContent) content: IonContent;
  article: IArticleDetailModel;
  tags: IArticleTagModel[] = [];
  links: IHelpfulLinkModel[] = [];
  isUserLikedLoading = true;
  queryText = '';
  showSearchbar = false;
  instagram: string | SafeUrl = '';
  twiter: string | SafeUrl = '';
  facebook: string | SafeUrl = '';
  telegram: string | SafeUrl = '';
  pinterest: string | SafeUrl = '';
  aparat: string | SafeUrl = '';
  discord: string | SafeUrl = '';
  youtube: string | SafeUrl = '';
  twitch: string | SafeUrl = '';
  linkedin: string | SafeUrl = '';
  whatsappShare: SafeUrl = '';
  isLikeLoadingShow = false;
  isLoading = true;
  windowWidth = 1000;

  constructor(
    private activatedRoute: ActivatedRoute,
    private articleService: ArticleService,
    public loadingController: LoadingController,
    public toastController: ToastController,
    private router: Router,
    private title: Title,
    private meta: Meta,
    private domSanitizer: DomSanitizer
  ) {
    G.getWindowWidth().subscribe(
      res => {
        this.windowWidth = res;
      }
    );
  }

  goTop() {
    this.content.scrollToTop(3000);
  }

  updateTitle(title: string = 'اول آموز - راهنمای محصولات و کاربرگ‌های آموزشی دبستان') {
    this.title.setTitle(title);
    this.meta.updateTag({ name: 'og:title', content: title });
    this.meta.updateTag({ name: 'twitter:title', content: title });
    this.meta.updateTag({ property: 'og:title', content: title });
    this.meta.updateTag({ itemprop: 'name', content: title });
  }

  updateOgUrl(url: string = 'http://localhost:4300/') {
    this.meta.updateTag({ name: 'og:url', content: url });
    this.meta.updateTag({ name: 'twitter:url', content: url });
    this.meta.updateTag({ name: 'og:image', content: this.article.imageNamePNG });
    this.meta.updateTag({ property: 'og:image', content: this.article.imageNamePNG });
    this.meta.updateTag({ name: 'twitter:image', content: this.article.imageNamePNG });
    this.meta.updateTag({ name: 'og:image:alt', content: this.article.name });
    this.meta.updateTag({ property: 'og:image:alt', content: this.article.name });
  }

  updateDescription(desc: string = 'اول آموز مرجع تخصصی دوره‌های روش تدریس، کاربرگ‌های آموزشی و ملزومات پایه‌های اول تا ششم دبستان است') {
    this.meta.updateTag({ name: 'description', content: desc });
    this.meta.updateTag({ name: 'twitter:description', content: desc });
    this.meta.updateTag({ name: 'og:description', content: desc });
    this.meta.updateTag({ property: 'og:description', content: desc });
    this.meta.updateTag({ itemprop: 'description', content: desc });
  }

  forwardUrl(url: string) {
    window.location.href = url;
  }

  copyText(val: string) {
    const selBox = document.createElement('textarea');
    selBox.style.position = 'fixed';
    selBox.style.left = '0';
    selBox.style.top = '0';
    selBox.style.opacity = '0';
    selBox.value = val;
    document.body.appendChild(selBox);
    selBox.focus();
    selBox.select();
    document.execCommand('copy');
    document.body.removeChild(selBox);

    SharedIonic.toast(this.toastController, 'کپی شد');
  }

  doRefresh(event) {

    setTimeout(() => {
      location.reload();
      event.target.complete();
    }, 2000);
  }

  getData(id: number) {

    this.articleService.GetProductArticleDetailById(id).subscribe(
      ress => {
        this.isLoading = false;
        SharedIonic.dismissLoading(this.loadingController);
        if (ress.status === GResponse.SuccessStatus) {
          this.article = ress.data;

          this.whatsappShare = this.domSanitizer.bypassSecurityTrustUrl('whatsapp://send?text=http://localhost:4300/pa/' + this.article.id);

          this.updateTitle('اول آموز - ' + this.article.name);
          this.updateOgUrl('http://localhost:4300/pa/' + this.article.id);
          this.updateDescription('اول آموز - ' + this.article.shortDescription);

          this.articleService.GetProductArticleTags(+id).subscribe(
            res => {
              if (GResponse.SuccessStatus === res.status) {
                this.tags = res.data;
              } else {

              }
            },
            err => {

            }
          );

          if (GAccount.IsLoggedIn()) {

            this.articleService.GetProductArticleDetailUserLikedById(id).subscribe(
              res => {
                if (GResponse.SuccessStatus === res.status) {

                  switch (res.data) {
                    case -1:
                      this.article.userLiked = null;
                      break;
                    case 0:
                      this.article.userLiked = false;
                      break;
                    case 1:
                      this.article.userLiked = true;
                      break;

                    default:
                      this.article.userLiked = null;
                      break;
                  }

                  this.isUserLikedLoading = false;

                } else {
                  this.article.userLiked = null;
                  this.isUserLikedLoading = false;
                }
              },
              err => {
                this.article.userLiked = null;
                this.isUserLikedLoading = false;
              }
            );
          } else {
            this.article.userLiked = null;
            this.isUserLikedLoading = false;
          }

          this.articleService.GetProductArticleDetailViewedShowById(id).subscribe(
            res => {
              if (GResponse.SuccessStatus === res.status) {
                this.article.viewCount = res.data;
              } else {
                this.article.viewCount = 1;
              }
            },
            err => {
              this.article.viewCount = 1;
            }
          );

          this.articleService.GetArticleDetailSellerById(id).subscribe(
            res => {
              if (GResponse.SuccessStatus === res.status) {
                this.article.teacherUser = new TeacherModel(
                  res.data.id,
                  res.data.name,
                  res.data.family,
                  res.data.resume,
                  res.data.userAvatarAddress,
                  res.data.isRested
                );
              } else {
                this.article.teacherUser = null;
              }
            },
            err => {
              this.article.teacherUser = null;
            }
          );

          if (GAccount.IsLoggedIn() && GAccount.IsBuyer()) {
            this.articleService.AddOrUpdateUserViewedProductArticle(ress.data.id).subscribe(
              res => {
                if (res.status === GResponse.SuccessStatus) {
                  this.article.viewCount++;
                }
              }
            );
          }
        } else {
          SharedIonic.dismissLoading(this.loadingController);
          // this.router.navigateByUrl(Urls.Page404Url);
        }
      },
      err => {
        this.isLoading = false;
        SharedIonic.dismissLoading(this.loadingController);
        this.router.navigateByUrl(Urls.Page404Url);
      });
  }

  ngOnInit(): void {

    this.instagram = G.Instagram;
    this.twiter = G.Twiter;
    this.facebook = G.Facebook;
    this.telegram = G.Telegram;
    this.youtube = G.Youtube;
    this.pinterest = G.Pinterest;
    this.linkedin = G.Linkedin;
    this.twitch = G.Twitch;
    this.aparat = G.Aparat;
    this.discord = G.Discord;

    G.getHelpfulLinks().subscribe(
      res => {
        if (res != null) {
          if (res.length > 0) {
            res.forEach(link => {
              this.links.push(link);
            });
          }
        }
      }
    );

    SharedIonic.loading(this.loadingController);

    this.activatedRoute.params.subscribe(params => {

      // tslint:disable-next-line: radix
      const id = parseInt(params.id, 10);

      this.isUserLikedLoading = true;

      this.getData(+id);
    });
  }

  getTeacherName() {

    if (this.article.sellerUser == undefined || this.article.sellerUser == null) {

      return '';
    }
    const name = this.article.sellerUser.name != null ? this.article.sellerUser.name : '';
    const family = this.article.sellerUser.family != null ? this.article.sellerUser.family : '';

    return name + ' ' + family;
  }

  ionViewWillEnter() {


  }

  onNavigate(url: string) {

    this.router.navigateByUrl(url);
  }

  onCancel() {
    this.showSearchbar = false;
  }

  search() {

    if (this.queryText == null || this.queryText.length < 1) {
      return;
    }

    this.router
      .navigate(
        ['Product', 'Search'],
        {
          queryParams:
          {
            title: this.queryText
          }
        });
  }

  OnLike(like: boolean) {

    if (GAccount.IsLoggedIn() && GAccount.IsBuyer()) {

      this.isLikeLoadingShow = true;

      this.articleService.AddOrUpdateUserLikedProductArticle(this.article.id, like).subscribe(
        res => {
          this.isLikeLoadingShow = false;
          if (res.status === GResponse.SuccessStatus) {
            this.article.userLiked = like;
          }
        },
        err => {
          this.isLikeLoadingShow = false;
        }
      );
    }
  }

  isLikeShow(): boolean {

    return GAccount.IsLoggedIn();
  }
}
